export function WhyChooseSection() {
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  return (
    <section className={styles.section} aria-labelledby="why-choose-title">
      <div className={styles.container}>
        <h2 id="why-choose-title" className={styles.title}>
          Why Choose White Hawk?
        </h2>
        <p className={styles.subtitle}>
          With White Hawk, you don&apos;t just get a tool—you get a
          comprehensive, proactive cybersecurity solution that scales with your
          business.
        </p>

        <div className={styles.trackWrap}>
          {/* Connected grid: top horizontal line */}
          <div className={styles.lineTop} aria-hidden />
          {/* Connected grid: bottom horizontal line */}
          <div className={styles.lineBottom} aria-hidden />

          <div className={styles.track}>
            {FEATURES.map((feature, index) => {
              const isOpen = openIndex === index;
              return (
                <div
                  key={feature.id}
                  className={`${styles.item} ${isOpen ? styles.itemOpen : ""}`}
                >
                  {/* Icon column: line + dots always aligned with icon center */}
                  <div className={styles.iconColumn}>
                    <span className={styles.verticalLine} aria-hidden />
                    <span className={styles.dotTop} aria-hidden />
                    <span className={styles.dotBottom} aria-hidden />
                    {isOpen ? (
                      <button
                        type="button"
                        className={styles.cardIconBtn}
                        onClick={() => setOpenIndex(0)}
                        aria-expanded={true}
                        aria-controls={`why-card-body-${index}`}
                        id={`why-card-heading-${index}`}
                        title={feature.title}
                      >
                        <span className={styles.cardIconWrap}>
                          <span className={styles.cardIcon}>
                            {ICON_SVG[feature.icon]}
                          </span>
                        </span>
                      </button>
                    ) : (
                      <button
                        type="button"
                        className={styles.dot}
                        onClick={() => setOpenIndex(index)}
                        aria-expanded={false}
                        aria-controls={`why-card-body-${index}`}
                        title={feature.title}
                      >
                        <span className={styles.dotIconWrap}>
                          <span className={styles.dotIcon}>
                            {ICON_SVG[feature.icon]}
                          </span>
                        </span>
                      </button>
                    )}
                  </div>
                  {isOpen && (
                    <div
                      id={`why-card-body-${index}`}
                      className={styles.cardBody}
                      role="region"
                      aria-labelledby={`why-card-heading-${index}`}
                    >
                      <h3 className={styles.cardTitle}>{feature.title}</h3>
                      <p className={styles.cardDescription}>
                        {feature.description}
                      </p>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* <div className={styles.useCasesDivider}>
          <span className={styles.useCasesLine} />
          <span className={styles.useCasesLabel}>USE CASES</span>
          <span className={styles.useCasesLine} />
        </div> */}
      </div>
    </section>
  );
}
